"use client"

import { useEffect, useImperativeHandle, useRef, useState } from "react"
import { dropCursor } from "prosemirror-dropcursor"
import { gapCursor } from "prosemirror-gapcursor"
import { history } from "prosemirror-history"
import { EditorState } from "prosemirror-state"
import { EditorView } from "prosemirror-view"

import { EditorToolbar } from "@/components/ui/editor/editor-toolbar"
import { toggleTaskAt } from "@/components/ui/editor/commands"
import { fromMarkdown, toMarkdown } from "@/components/ui/editor/lib/markdown"
import { buildInputRules } from "@/components/ui/editor/plugins/input-rules"
import { buildKeymap } from "@/components/ui/editor/plugins/keymap"
import { imageUploadPlugin, type UploadHandler } from "@/components/ui/editor/plugins/image-upload"
import { placeholderPlugin } from "@/components/ui/editor/plugins/placeholder"
import { schema } from "@/components/ui/editor/schema"

export type EditorHandle = {
  /** Foca o editor e leva o cursor para o fim do documento. */
  focus: () => void
  /** Markdown atual, sem esperar o `onChange`. */
  getMarkdown: () => string
  /** Troca o conteúdo — use para limpar o campo depois de enviar. */
  setMarkdown: (markdown: string) => void
}

export type EditorProps = {
  /** Conteúdo em Markdown. Mudanças externas substituem o documento. */
  value: string
  onChange?: (markdown: string) => void
  /** Recebe o arquivo colado, arrastado ou escolhido e devolve a URL pública. */
  onUpload?: UploadHandler
  /** Disparado por Ctrl/⌘+Enter. */
  onSubmit?: () => void
  onFocus?: () => void
  onBlur?: () => void
  placeholder?: string
  readOnly?: boolean
  autoFocus?: boolean
  /** Barra flutuante sobre a seleção, barra fixa no topo ou nenhuma. */
  toolbar?: "floating" | "fixed" | "none"
  className?: string
  ref?: React.Ref<EditorHandle>
}

/**
 * Editor de conteúdo em Markdown. O estado real vive no ProseMirror; o React só
 * hospeda o nó e observa a seleção para desenhar a barra de ferramentas.
 */
export function Editor({
  value,
  onChange,
  onUpload,
  onSubmit,
  onFocus,
  onBlur,
  placeholder = "Escreva alguma coisa...",
  readOnly = false,
  autoFocus = false,
  toolbar = "floating",
  className,
  ref,
}: EditorProps) {
  const hostRef = useRef<HTMLDivElement>(null)
  const viewRef = useRef<EditorView | null>(null)
  /** Último Markdown que saiu daqui: evita reconstruir o documento no próprio eco. */
  const lastMarkdown = useRef(value)
  const callbacks = useRef({ onChange, onSubmit, onUpload, onFocus, onBlur })
  const [view, setView] = useState<EditorView | null>(null)
  const [, forceRender] = useState(0)

  // As callbacks vivem em ref para que a view não seja recriada (e o histórico perdido)
  // a cada render do host; a escrita acontece depois da renderização.
  useEffect(() => {
    callbacks.current = { onChange, onSubmit, onUpload, onFocus, onBlur }
  })

  useEffect(() => {
    const host = hostRef.current
    if (!host) return

    const state = EditorState.create({
      doc: fromMarkdown(lastMarkdown.current),
      plugins: [
        buildInputRules(),
        ...buildKeymap({ onSubmit: () => callbacks.current.onSubmit?.() }),
        ...imageUploadPlugin(callbacks.current.onUpload),
        history(),
        dropCursor({ color: "var(--flynow-editor-caret, currentColor)" }),
        gapCursor(),
        placeholderPlugin(placeholder),
      ],
    })

    const instance = new EditorView(host, {
      state,
      editable: () => !readOnly,
      attributes: { class: "flynow-editor-content", spellcheck: "true" },
      dispatchTransaction(transaction) {
        const proximo = instance.state.apply(transaction)
        instance.updateState(proximo)

        if (transaction.docChanged) {
          const markdown = toMarkdown(proximo.doc)
          lastMarkdown.current = markdown
          callbacks.current.onChange?.(markdown)
        }

        // A barra depende da seleção, então acompanha qualquer transação.
        forceRender((contador) => contador + 1)
      },
      handleClickOn(clickView, _pos, node, nodePos, event) {
        // Clique no quadradinho da tarefa alterna a marcação sem mover o cursor.
        const alvo = event.target as HTMLElement
        if (node.type !== schema.nodes.task_item || alvo.tagName !== "INPUT") return false

        return toggleTaskAt(clickView, nodePos)
      },
    })

    // focus/blur ficam no DOM: o `handleDOMEvents` da view não recebe estes dois.
    const aoFocar = () => callbacks.current.onFocus?.()
    const aoSair = () => callbacks.current.onBlur?.()
    instance.dom.addEventListener("focus", aoFocar)
    instance.dom.addEventListener("blur", aoSair)

    viewRef.current = instance
    setView(instance)
    if (autoFocus) instance.focus()

    return () => {
      instance.dom.removeEventListener("focus", aoFocar)
      instance.dom.removeEventListener("blur", aoSair)
      instance.destroy()
      viewRef.current = null
      setView(null)
    }
    // Recriar a view a cada mudança de callback perderia o histórico; elas vivem no ref.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Conteúdo vindo de fora (carregou da API, outro usuário salvou) substitui o documento.
  useEffect(() => {
    const instance = viewRef.current
    if (!instance || value === lastMarkdown.current) return

    lastMarkdown.current = value
    const doc = fromMarkdown(value)
    const state = EditorState.create({ doc, plugins: instance.state.plugins })
    instance.updateState(state)
  }, [value])

  useEffect(() => {
    viewRef.current?.setProps({ editable: () => !readOnly })
  }, [readOnly])

  useImperativeHandle(
    ref,
    () => ({
      focus: () => {
        const instance = viewRef.current
        if (!instance) return
        instance.focus()
      },
      getMarkdown: () => (viewRef.current ? toMarkdown(viewRef.current.state.doc) : ""),
      setMarkdown: (markdown: string) => {
        const instance = viewRef.current
        if (!instance) return

        lastMarkdown.current = markdown
        instance.updateState(
          EditorState.create({ doc: fromMarkdown(markdown), plugins: instance.state.plugins })
        )
      },
    }),
    []
  )

  return (
    <div className={["flynow-editor", className].filter(Boolean).join(" ")}>
      {view && toolbar !== "none" && !readOnly ? (
        <EditorToolbar view={view} variant={toolbar} onUpload={onUpload} />
      ) : null}
      <div ref={hostRef} />
    </div>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"
import type { EditorView } from "prosemirror-view"

import {
  isBlockActive,
  isListActive,
  isMarkActive,
  run,
  setLink,
  toggleBlockquote,
  toggleCode,
  toggleCodeBlock,
  toggleEm,
  toggleHeading,
  toggleList,
  toggleStrike,
  toggleStrong,
} from "@/components/ui/editor/commands"
import { uploadImageFile, type UploadHandler } from "@/components/ui/editor/plugins/image-upload"
import { schema } from "@/components/ui/editor/schema"

type ToolbarButtonProps = {
  label: string
  active?: boolean
  onClick: () => void
  children: React.ReactNode
}

function ToolbarButton({ label, active, onClick, children }: ToolbarButtonProps) {
  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      aria-pressed={active}
      data-active={active || undefined}
      // O mousedown padrão tiraria a seleção do editor antes do clique chegar.
      onMouseDown={(event) => event.preventDefault()}
      onClick={onClick}
      className="flynow-editor-toolbar-button"
    >
      {children}
    </button>
  )
}

function Divider() {
  return <span aria-hidden className="flynow-editor-toolbar-divider" />
}

type EditorToolbarProps = {
  view: EditorView
  variant: "floating" | "fixed"
  onUpload?: UploadHandler
}

/**
 * Barra de ferramentas. Na variante flutuante ela só aparece com texto selecionado
 * e se posiciona acima da seleção, como no Linear.
 */
export function EditorToolbar({ view, variant, onUpload }: EditorToolbarProps) {
  const barRef = useRef<HTMLDivElement>(null)
  const fileRef = useRef<HTMLInputElement>(null)
  const [position, setPosition] = useState<{ top: number; left: number } | null>(null)

  const { state } = view
  const flutuante = variant === "floating"
  const selecaoVazia = state.selection.empty

  useEffect(() => {
    if (!flutuante) return

    const barra = barRef.current
    if (!barra || selecaoVazia) {
      setPosition(null)
      return
    }

    const inicio = view.coordsAtPos(state.selection.from)
    const fim = view.coordsAtPos(state.selection.to)
    const referencia = barra.offsetParent as HTMLElement | null
    const caixa = referencia?.getBoundingClientRect()

    const meio = (Math.min(inicio.left, fim.left) + Math.max(inicio.right, fim.right)) / 2
    const topo = Math.min(inicio.top, fim.top)

    setPosition({
      top: topo - (caixa?.top ?? 0) - barra.offsetHeight - 8,
      left: Math.max(0, meio - (caixa?.left ?? 0) - barra.offsetWidth / 2),
    })
  }, [flutuante, selecaoVazia, state.selection.from, state.selection.to, view])

  if (flutuante && selecaoVazia) return null

  const acoes = (
    <>
      <ToolbarButton
        label="Título 1"
        active={isBlockActive(state, schema.nodes.heading, { level: 1 })}
        onClick={() => run(view, toggleHeading(1))}
      >
        H1
      </ToolbarButton>
      <ToolbarButton
        label="Título 2"
        active={isBlockActive(state, schema.nodes.heading, { level: 2 })}
        onClick={() => run(view, toggleHeading(2))}
      >
        H2
      </ToolbarButton>
      <ToolbarButton
        label="Título 3"
        active={isBlockActive(state, schema.nodes.heading, { level: 3 })}
        onClick={() => run(view, toggleHeading(3))}
      >
        H3
      </ToolbarButton>

      <Divider />

      <ToolbarButton
        label="Negrito"
        active={isMarkActive(state, schema.marks.strong)}
        onClick={() => run(view, toggleStrong())}
      >
        <strong>B</strong>
      </ToolbarButton>
      <ToolbarButton
        label="Itálico"
        active={isMarkActive(state, schema.marks.em)}
        onClick={() => run(view, toggleEm())}
      >
        <em>I</em>
      </ToolbarButton>
      <ToolbarButton
        label="Riscado"
        active={isMarkActive(state, schema.marks.strike)}
        onClick={() => run(view, toggleStrike())}
      >
        <s>S</s>
      </ToolbarButton>
      <ToolbarButton
        label="Código"
        active={isMarkActive(state, schema.marks.code)}
        onClick={() => run(view, toggleCode())}
      >
        <code>{"<>"}</code>
      </ToolbarButton>
      <ToolbarButton
        label="Link"
        active={isMarkActive(state, schema.marks.link)}
        onClick={() => {
          const atual = isMarkActive(state, schema.marks.link)
          if (atual) {
            run(view, setLink(null))
            return
          }

          const href = window.prompt("Endereço do link")
          if (href) run(view, setLink(href))
        }}
      >
        🔗
      </ToolbarButton>

      <Divider />

      <ToolbarButton
        label="Lista"
        active={isListActive(state, schema.nodes.bullet_list)}
        onClick={() => run(view, toggleList(schema.nodes.bullet_list))}
      >
        •
      </ToolbarButton>
      <ToolbarButton
        label="Lista numerada"
        active={isListActive(state, schema.nodes.ordered_list)}
        onClick={() => run(view, toggleList(schema.nodes.ordered_list))}
      >
        1.
      </ToolbarButton>
      <ToolbarButton
        label="Lista de tarefas"
        active={isListActive(state, schema.nodes.task_list)}
        onClick={() => run(view, toggleList(schema.nodes.task_list))}
      >
        ☑
      </ToolbarButton>
      <ToolbarButton
        label="Citação"
        active={isBlockActive(state, schema.nodes.blockquote)}
        onClick={() => run(view, toggleBlockquote())}
      >
        ❝
      </ToolbarButton>
      <ToolbarButton
        label="Bloco de código"
        active={isBlockActive(state, schema.nodes.code_block)}
        onClick={() => run(view, toggleCodeBlock())}
      >
        {"{ }"}
      </ToolbarButton>

      {onUpload ? (
        <>
          <Divider />
          <ToolbarButton label="Imagem" onClick={() => fileRef.current?.click()}>
            🖼
          </ToolbarButton>
          <input
            ref={fileRef}
            type="file"
            accept="image/*"
            hidden
            onChange={(event) => {
              const file = event.target.files?.[0]
              if (file) uploadImageFile(view, file, onUpload)
              event.target.value = ""
            }}
          />
        </>
      ) : null}
    </>
  )

  return (
    <div
      ref={barRef}
      role="toolbar"
      aria-label="Formatação"
      data-variant={variant}
      className="flynow-editor-toolbar"
      style={
        flutuante
          ? { top: position?.top ?? 0, left: position?.left ?? 0, visibility: position ? "visible" : "hidden" }
          : undefined
      }
    >
      {acoes}
    </div>
  )
}

/*
 * Tema do editor. Tudo sai de variáveis: o projeto que instala sobrescreve o que
 * quiser (cores, raio, espaçamento) sem tocar no restante do arquivo.
 */
.flynow-editor {
  --flynow-editor-fg: var(--foreground, #111);
  --flynow-editor-muted: var(--muted-foreground, #71717a);
  --flynow-editor-border: var(--border, #e4e4e7);
  --flynow-editor-accent: var(--accent, #f4f4f5);
  --flynow-editor-surface: var(--popover, #fff);
  --flynow-editor-code-bg: color-mix(in oklab, var(--flynow-editor-fg) 8%, transparent);
  --flynow-editor-radius: var(--radius, 0.5rem);
  --flynow-editor-gap: 0.75rem;

  position: relative;
  color: var(--flynow-editor-fg);
}

/* Conteúdo ------------------------------------------------------------------ */

.flynow-editor-content {
  outline: none;
  white-space: pre-wrap;
  word-wrap: break-word;
  font-size: 0.875rem;
  line-height: 1.65;
}

.flynow-editor-content > * + * {
  margin-top: var(--flynow-editor-gap);
}

.flynow-editor-content h1,
.flynow-editor-content h2,
.flynow-editor-content h3 {
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.015em;
}

.flynow-editor-content h1 {
  font-size: 1.5rem;
}
.flynow-editor-content h2 {
  font-size: 1.25rem;
}
.flynow-editor-content h3 {
  font-size: 1.05rem;
}

.flynow-editor-content a {
  color: var(--primary, #2563eb);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.flynow-editor-content code {
  background: var(--flynow-editor-code-bg);
  border-radius: 0.25rem;
  padding: 0.1em 0.3em;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace);
  font-size: 0.85em;
}

.flynow-editor-content pre {
  background: var(--flynow-editor-code-bg);
  border-radius: var(--flynow-editor-radius);
  padding: 0.75rem 1rem;
  overflow-x: auto;
}

.flynow-editor-content pre code {
  background: none;
  padding: 0;
  font-size: 0.85em;
}

.flynow-editor-content blockquote {
  border-left: 2px solid var(--flynow-editor-border);
  padding-left: 0.875rem;
  color: var(--flynow-editor-muted);
}

.flynow-editor-content hr {
  border: none;
  border-top: 1px solid var(--flynow-editor-border);
}

.flynow-editor-content ul,
.flynow-editor-content ol {
  padding-left: 1.4rem;
}

.flynow-editor-content ul {
  list-style: disc;
}

.flynow-editor-content ol {
  list-style: decimal;
}

.flynow-editor-content li + li {
  margin-top: 0.25rem;
}

.flynow-editor-content li > p {
  margin: 0;
}

.flynow-editor-content img {
  max-width: 100%;
  height: auto;
  border-radius: var(--flynow-editor-radius);
}

/* Lista de tarefas ---------------------------------------------------------- */

.flynow-editor-content ul[data-type="task-list"] {
  list-style: none;
  padding-left: 0.15rem;
}

.flynow-editor-content li[data-type="task-item"] {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
}

.flynow-editor-content li[data-type="task-item"] > label {
  display: flex;
  align-items: center;
  height: 1.65em;
}

.flynow-editor-content li[data-type="task-item"] input {
  cursor: pointer;
  accent-color: var(--primary, #2563eb);
}

.flynow-editor-content li[data-type="task-item"] > div {
  flex: 1;
  min-width: 0;
}

.flynow-editor-content li[data-type="task-item"][data-checked="true"] > div {
  color: var(--flynow-editor-muted);
  text-decoration: line-through;
}

/* Estados ------------------------------------------------------------------- */

.flynow-editor-placeholder::before {
  content: attr(data-placeholder);
  color: var(--flynow-editor-muted);
  float: left;
  height: 0;
  pointer-events: none;
}

.flynow-editor-uploading {
  color: var(--flynow-editor-muted);
  font-size: 0.8em;
  border: 1px dashed var(--flynow-editor-border);
  border-radius: var(--flynow-editor-radius);
  padding: 0.1rem 0.4rem;
}

.flynow-editor .ProseMirror-selectednode {
  outline: 2px solid var(--primary, #2563eb);
  outline-offset: 2px;
}

/* Barra de ferramentas ------------------------------------------------------ */

.flynow-editor-toolbar {
  display: flex;
  align-items: center;
  gap: 0.125rem;
  padding: 0.25rem;
  border-radius: calc(var(--flynow-editor-radius) + 0.125rem);
  background: var(--flynow-editor-surface);
  box-shadow: 0 10px 30px -12px rgb(0 0 0 / 45%);
  ring: 1px;
  border: 1px solid var(--flynow-editor-border);
}

.flynow-editor-toolbar[data-variant="floating"] {
  position: absolute;
  z-index: 30;
}

.flynow-editor-toolbar[data-variant="fixed"] {
  margin-bottom: 0.5rem;
}

.flynow-editor-toolbar-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.75rem;
  height: 1.75rem;
  padding: 0 0.375rem;
  border-radius: calc(var(--flynow-editor-radius) - 0.125rem);
  color: var(--flynow-editor-muted);
  font-size: 0.8rem;
  line-height: 1;
  transition:
    background-color 120ms ease,
    color 120ms ease;
}

.flynow-editor-toolbar-button:hover {
  background: var(--flynow-editor-accent);
  color: var(--flynow-editor-fg);
}

.flynow-editor-toolbar-button[data-active] {
  color: var(--primary, #2563eb);
  background: color-mix(in oklab, var(--primary, #2563eb) 14%, transparent);
}

.flynow-editor-toolbar-divider {
  width: 1px;
  height: 1.1rem;
  margin: 0 0.25rem;
  background: var(--flynow-editor-border);
}

import { Schema, type DOMOutputSpec, type NodeSpec, type MarkSpec } from "prosemirror-model"

/**
 * Blocos do documento. A ordem importa: o primeiro nó de cada grupo é o padrão
 * usado quando o ProseMirror precisa preencher um espaço vazio.
 */
const nodes: Record<string, NodeSpec> = {
  doc: { content: "block+" },

  paragraph: {
    content: "inline*",
    group: "block",
    parseDOM: [{ tag: "p" }],
    toDOM: (): DOMOutputSpec => ["p", 0],
  },

  heading: {
    attrs: { level: { default: 1 } },
    content: "inline*",
    group: "block",
    defining: true,
    parseDOM: [
      { tag: "h1", attrs: { level: 1 } },
      { tag: "h2", attrs: { level: 2 } },
      { tag: "h3", attrs: { level: 3 } },
    ],
    toDOM: (node): DOMOutputSpec => [`h${node.attrs.level}`, 0],
  },

  blockquote: {
    content: "block+",
    group: "block",
    defining: true,
    parseDOM: [{ tag: "blockquote" }],
    toDOM: (): DOMOutputSpec => ["blockquote", 0],
  },

  code_block: {
    attrs: { language: { default: null } },
    content: "text*",
    marks: "",
    group: "block",
    code: true,
    defining: true,
    parseDOM: [
      {
        tag: "pre",
        preserveWhitespace: "full",
        getAttrs: (dom) => ({
          language: (dom as HTMLElement).getAttribute("data-language"),
        }),
      },
    ],
    toDOM: (node): DOMOutputSpec => [
      "pre",
      node.attrs.language ? { "data-language": node.attrs.language } : {},
      ["code", 0],
    ],
  },

  bullet_list: {
    content: "list_item+",
    group: "block",
    parseDOM: [{ tag: "ul" }],
    toDOM: (): DOMOutputSpec => ["ul", 0],
  },

  ordered_list: {
    attrs: { order: { default: 1 } },
    content: "list_item+",
    group: "block",
    parseDOM: [
      {
        tag: "ol",
        getAttrs: (dom) => ({
          order: Number((dom as HTMLElement).getAttribute("start")) || 1,
        }),
      },
    ],
    toDOM: (node): DOMOutputSpec =>
      node.attrs.order === 1 ? ["ol", 0] : ["ol", { start: node.attrs.order }, 0],
  },

  list_item: {
    content: "paragraph block*",
    defining: true,
    parseDOM: [{ tag: "li" }],
    toDOM: (): DOMOutputSpec => ["li", 0],
  },

  task_list: {
    content: "task_item+",
    group: "block",
    parseDOM: [{ tag: "ul[data-type=task-list]" }],
    toDOM: (): DOMOutputSpec => ["ul", { "data-type": "task-list" }, 0],
  },

  /** O quadradinho é o próprio DOM do item; a marcação vive em `checked`. */
  task_item: {
    attrs: { checked: { default: false } },
    content: "paragraph block*",
    defining: true,
    parseDOM: [
      {
        tag: "li[data-type=task-item]",
        getAttrs: (dom) => ({
          checked: (dom as HTMLElement).getAttribute("data-checked") === "true",
        }),
      },
    ],
    toDOM: (node): DOMOutputSpec => [
      "li",
      { "data-type": "task-item", "data-checked": String(node.attrs.checked) },
      ["label", ["input", { type: "checkbox", ...(node.attrs.checked ? { checked: "" } : {}) }]],
      ["div", 0],
    ],
  },

  horizontal_rule: {
    group: "block",
    parseDOM: [{ tag: "hr" }],
    toDOM: (): DOMOutputSpec => ["hr"],
  },

  image: {
    inline: true,
    attrs: {
      src: {},
      alt: { default: null },
      title: { default: null },
    },
    group: "inline",
    draggable: true,
    parseDOM: [
      {
        tag: "img[src]",
        getAttrs: (dom) => ({
          src: (dom as HTMLElement).getAttribute("src"),
          alt: (dom as HTMLElement).getAttribute("alt"),
          title: (dom as HTMLElement).getAttribute("title"),
        }),
      },
    ],
    toDOM: (node): DOMOutputSpec => ["img", node.attrs],
  },

  hard_break: {
    inline: true,
    group: "inline",
    selectable: false,
    parseDOM: [{ tag: "br" }],
    toDOM: (): DOMOutputSpec => ["br"],
  },

  text: { group: "inline" },
}

/** Formatações inline. `code` exclui as demais para não gerar Markdown inválido. */
const marks: Record<string, MarkSpec> = {
  strong: {
    parseDOM: [
      { tag: "strong" },
      { tag: "b", getAttrs: (dom) => (dom as HTMLElement).style.fontWeight !== "normal" && null },
      { style: "font-weight=bold" },
      { style: "font-weight=700" },
    ],
    toDOM: (): DOMOutputSpec => ["strong", 0],
  },

  em: {
    parseDOM: [{ tag: "i" }, { tag: "em" }, { style: "font-style=italic" }],
    toDOM: (): DOMOutputSpec => ["em", 0],
  },

  strike: {
    parseDOM: [{ tag: "s" }, { tag: "del" }, { style: "text-decoration=line-through" }],
    toDOM: (): DOMOutputSpec => ["s", 0],
  },

  code: {
    excludes: "_",
    code: true,
    parseDOM: [{ tag: "code" }],
    toDOM: (): DOMOutputSpec => ["code", 0],
  },

  link: {
    attrs: { href: {}, title: { default: null } },
    inclusive: false,
    parseDOM: [
      {
        tag: "a[href]",
        getAttrs: (dom) => ({
          href: (dom as HTMLElement).getAttribute("href"),
          title: (dom as HTMLElement).getAttribute("title"),
        }),
      },
    ],
    toDOM: (mark): DOMOutputSpec => [
      "a",
      { ...mark.attrs, rel: "noopener noreferrer nofollow", target: "_blank" },
      0,
    ],
  },
}

/** Documento do editor. Trocar um nó aqui muda o que o Markdown aceita dos dois lados. */
export const schema = new Schema({ nodes, marks })

import { lift, setBlockType, toggleMark, wrapIn } from "prosemirror-commands"
import type { MarkType, Node as ProseNode, NodeType } from "prosemirror-model"
import { liftListItem, wrapInList } from "prosemirror-schema-list"
import type { Command, EditorState, Transaction } from "prosemirror-state"
import type { EditorView } from "prosemirror-view"

import { schema } from "@/components/ui/editor/schema"

type Dispatch = ((tr: Transaction) => void) | undefined

/** A marca está aplicada na seleção (ou vale para o próximo caractere digitado)? */
export function isMarkActive(state: EditorState, type: MarkType): boolean {
  const { from, $from, to, empty } = state.selection

  if (empty) return Boolean(type.isInSet(state.storedMarks || $from.marks()))
  return state.doc.rangeHasMark(from, to, type)
}

/**
 * O bloco da seleção é deste tipo (e com estes atributos)? Só os atributos passados
 * são comparados — `hasMarkup` exigiria repetir todos os padrões do nó.
 */
export function isBlockActive(
  state: EditorState,
  type: NodeType,
  attrs: Record<string, unknown> = {}
): boolean {
  const { $from, to, node } = state.selection as EditorState["selection"] & {
    node?: ProseNode
  }

  const alvo = node ?? $from.parent
  if (!node && to > $from.end()) return false
  if (alvo.type !== type) return false

  return Object.entries(attrs).every(([chave, valor]) => alvo.attrs[chave] === valor)
}

/** A seleção está dentro de uma lista deste tipo? */
export function isListActive(state: EditorState, type: NodeType): boolean {
  const { $from } = state.selection

  for (let profundidade = $from.depth; profundidade > 0; profundidade--) {
    if ($from.node(profundidade).type === type) return true
  }

  return false
}

/** Alterna entre o parágrafo e o título do nível pedido. */
export function toggleHeading(level: number): Command {
  return (state, dispatch) => {
    const ativo = isBlockActive(state, schema.nodes.heading, { level })
    const comando = ativo
      ? setBlockType(schema.nodes.paragraph)
      : setBlockType(schema.nodes.heading, { level })

    return comando(state, dispatch)
  }
}

/** Alterna o bloco de código; fora dele, volta para parágrafo. */
export function toggleCodeBlock(): Command {
  return (state, dispatch) => {
    const ativo = isBlockActive(state, schema.nodes.code_block)
    const comando = ativo
      ? setBlockType(schema.nodes.paragraph)
      : setBlockType(schema.nodes.code_block)

    return comando(state, dispatch)
  }
}

/** Entra na citação ou sai dela, conforme o estado atual. */
export function toggleBlockquote(): Command {
  return (state, dispatch) => {
    if (isListActive(state, schema.nodes.blockquote) || estaDentro(state, schema.nodes.blockquote)) {
      return lift(state, dispatch)
    }

    return wrapIn(schema.nodes.blockquote)(state, dispatch)
  }
}

function estaDentro(state: EditorState, type: NodeType): boolean {
  const { $from } = state.selection

  for (let profundidade = $from.depth; profundidade > 0; profundidade--) {
    if ($from.node(profundidade).type === type) return true
  }

  return false
}

/**
 * Alterna uma lista. Dentro da mesma lista, desfaz; dentro de outra, troca o tipo
 * sem perder o conteúdo dos itens.
 */
export function toggleList(type: NodeType): Command {
  return (state, dispatch, view) => {
    if (isListActive(state, type)) {
      const item = type === schema.nodes.task_list ? schema.nodes.task_item : schema.nodes.list_item
      return liftListItem(item)(state, dispatch)
    }

    const outras = [schema.nodes.bullet_list, schema.nodes.ordered_list, schema.nodes.task_list]
    const atual = outras.find((candidata) => candidata !== type && isListActive(state, candidata))

    if (atual) return convertList(atual, type)(state, dispatch)

    return wrapInList(type)(state, dispatch, view)
  }
}

/**
 * Troca o tipo da lista reescrevendo o nó inteiro: os itens são recriados com o
 * tipo que a nova lista aceita, então o texto sobrevive à conversão.
 */
function convertList(from: NodeType, to: NodeType): Command {
  return (state, dispatch) => {
    const { $from } = state.selection

    let profundidade = -1
    for (let nivel = $from.depth; nivel > 0; nivel--) {
      if ($from.node(nivel).type === from) {
        profundidade = nivel
        break
      }
    }

    if (profundidade === -1) return false

    const lista = $from.node(profundidade)
    const inicio = $from.before(profundidade)
    const itemType = to === schema.nodes.task_list ? schema.nodes.task_item : schema.nodes.list_item

    const itens: ProseNode[] = []
    lista.forEach((item) => {
      itens.push(itemType.createChecked(null, item.content))
    })

    if (dispatch) {
      const nova = to.createChecked(null, itens)
      dispatch(state.tr.replaceWith(inicio, inicio + lista.nodeSize, nova).scrollIntoView())
    }

    return true
  }
}

export function toggleStrong(): Command {
  return toggleMark(schema.marks.strong)
}

export function toggleEm(): Command {
  return toggleMark(schema.marks.em)
}

export function toggleStrike(): Command {
  return toggleMark(schema.marks.strike)
}

export function toggleCode(): Command {
  return toggleMark(schema.marks.code)
}

/** Aplica o link na seleção; sem href, remove o que houver. */
export function setLink(href: string | null): Command {
  return (state, dispatch) => {
    const { from, to, empty } = state.selection
    if (empty) return false

    if (!href) {
      if (dispatch) dispatch(state.tr.removeMark(from, to, schema.marks.link))
      return true
    }

    if (dispatch) {
      dispatch(state.tr.addMark(from, to, schema.marks.link.create({ href })))
    }

    return true
  }
}

/** Insere a imagem na posição do cursor. */
export function insertImage(attrs: { src: string; alt?: string | null }): Command {
  return (state, dispatch) => {
    const node = schema.nodes.image.create({ src: attrs.src, alt: attrs.alt ?? null })
    if (dispatch) dispatch(state.tr.replaceSelectionWith(node).scrollIntoView())
    return true
  }
}

/** Marca ou desmarca o item de tarefa que contém a posição. */
export function toggleTaskAt(view: EditorView, pos: number): boolean {
  const node = view.state.doc.nodeAt(pos)
  if (!node || node.type !== schema.nodes.task_item) return false

  const tr = view.state.tr.setNodeMarkup(pos, undefined, {
    ...node.attrs,
    checked: !node.attrs.checked,
  })
  view.dispatch(tr)

  return true
}

/** Executa um comando na view e devevolve o foco ao editor. */
export function run(view: EditorView, command: Command): void {
  const dispatch: Dispatch = view.dispatch.bind(view)
  command(view.state, dispatch, view)
  view.focus()
}

import MarkdownIt from "markdown-it"
import { MarkdownParser, MarkdownSerializer, type MarkdownSerializerState } from "prosemirror-markdown"
import type { Node as ProseNode } from "prosemirror-model"

import { schema } from "@/components/ui/editor/schema"

const TASK_PREFIX = /^\[([ xX])\]\s+/

/**
 * Só o que a regra usa do token do markdown-it. Descrever aqui evita depender do
 * caminho interno dos tipos, que muda entre versões e entre resoluções de módulo.
 */
type MarkdownToken = {
  type: string
  tag: string
  level: number
  content: string
  children?: MarkdownToken[] | null
  attrGet: (name: string) => string | null
  attrSet: (name: string, value: string) => void
}

/** Só o gancho de regras é usado; tipar assim independe da versão do markdown-it. */
type MarkdownItLike = {
  core: {
    ruler: {
      after: (
        anterior: string,
        nome: string,
        regra: (state: { tokens: MarkdownToken[] }) => boolean
      ) => void
    }
  }
}

/**
 * Listas de tarefa não existem no CommonMark. A regra reescreve os tokens da lista
 * em `task_list`/`task_item` quando os itens começam com `[ ]` ou `[x]`, e tira o
 * prefixo do texto — assim o parser do editor recebe nós próprios.
 */
function taskListPlugin(md: MarkdownItLike): void {
  md.core.ruler.after("inline", "task_list", (state) => {
    const tokens = state.tokens

    for (let index = 0; index < tokens.length; index++) {
      const abertura = tokens[index]
      if (abertura.type !== "bullet_list_open") continue

      const fechamento = tokens.findIndex(
        (token, posicao) => posicao > index && token.type === "bullet_list_close" && token.level === abertura.level
      )
      if (fechamento === -1) continue

      const itens = marcarItens(tokens, index + 1, fechamento, abertura.level + 1)
      if (itens === 0) continue

      abertura.type = "task_list_open"
      abertura.tag = "ul"
      tokens[fechamento].type = "task_list_close"
      tokens[fechamento].tag = "ul"
    }

    return true
  })
}

/** Marca os itens da lista que são tarefa e devolve quantos foram convertidos. */
function marcarItens(tokens: MarkdownToken[], inicio: number, fim: number, level: number): number {
  let convertidos = 0

  for (let index = inicio; index < fim; index++) {
    const token = tokens[index]
    if (token.type !== "list_item_open" || token.level !== level) continue

    const conteudo = tokens
      .slice(index + 1, fim)
      .find((candidato) => candidato.type === "inline")
    const marcado = conteudo?.content.match(TASK_PREFIX)
    if (!conteudo || !marcado) continue

    conteudo.content = conteudo.content.replace(TASK_PREFIX, "")
    // O primeiro filho do inline carrega o mesmo texto e é o que o parser lê.
    const primeiro = conteudo.children?.[0]
    if (primeiro?.type === "text") primeiro.content = primeiro.content.replace(TASK_PREFIX, "")

    token.type = "task_item_open"
    token.attrSet("checked", marcado[1] === " " ? "false" : "true")

    const fechamentoItem = tokens.findIndex(
      (candidato, posicao) =>
        posicao > index && candidato.type === "list_item_close" && candidato.level === token.level
    )
    if (fechamentoItem !== -1) tokens[fechamentoItem].type = "task_item_close"

    convertidos++
  }

  return convertidos
}

const markdownIt = MarkdownIt("commonmark", { html: false, linkify: true })
  .enable(["strikethrough", "linkify"])
  .use(taskListPlugin as Parameters<ReturnType<typeof MarkdownIt>["use"]>[0])

/** Markdown → documento do editor. */
export const markdownParser = new MarkdownParser(schema, markdownIt, {
  blockquote: { block: "blockquote" },
  paragraph: { block: "paragraph" },
  list_item: { block: "list_item" },
  bullet_list: { block: "bullet_list" },
  ordered_list: {
    block: "ordered_list",
    getAttrs: (token) => ({ order: Number(token.attrGet("start")) || 1 }),
  },
  task_list: { block: "task_list" },
  task_item: {
    block: "task_item",
    getAttrs: (token) => ({ checked: token.attrGet("checked") === "true" }),
  },
  heading: {
    block: "heading",
    getAttrs: (token) => ({ level: Math.min(Number(token.tag.slice(1)), 3) }),
  },
  code_block: { block: "code_block", noCloseToken: true },
  fence: {
    block: "code_block",
    getAttrs: (token) => ({ language: token.info || null }),
    noCloseToken: true,
  },
  hr: { node: "horizontal_rule" },
  image: {
    node: "image",
    getAttrs: (token) => ({
      src: token.attrGet("src"),
      title: token.attrGet("title") || null,
      alt: token.children?.[0]?.content || null,
    }),
  },
  hardbreak: { node: "hard_break" },
  em: { mark: "em" },
  strong: { mark: "strong" },
  s: { mark: "strike" },
  link: {
    mark: "link",
    getAttrs: (token) => ({
      href: token.attrGet("href"),
      title: token.attrGet("title") || null,
    }),
  },
  code_inline: { mark: "code", noCloseToken: true },
})

/** Escapa o que o serializador padrão trataria como marcação. */
function serializeTaskItem(state: MarkdownSerializerState, node: ProseNode): void {
  state.write(node.attrs.checked ? "[x] " : "[ ] ")
  state.renderContent(node)
}

/** Documento do editor → Markdown. */
export const markdownSerializer = new MarkdownSerializer(
  {
    blockquote: (state, node) => {
      state.wrapBlock("> ", null, node, () => state.renderContent(node))
    },
    code_block: (state, node) => {
      const language = node.attrs.language ?? ""
      state.write(`\`\`\`${language}\n`)
      state.text(node.textContent, false)
      state.ensureNewLine()
      state.write("```")
      state.closeBlock(node)
    },
    heading: (state, node) => {
      state.write(`${"#".repeat(node.attrs.level)} `)
      state.renderInline(node)
      state.closeBlock(node)
    },
    horizontal_rule: (state, node) => {
      state.write("---")
      state.closeBlock(node)
    },
    bullet_list: (state, node) => {
      state.renderList(node, "  ", () => "- ")
    },
    ordered_list: (state, node) => {
      const inicio = node.attrs.order || 1
      const largura = String(inicio + node.childCount - 1).length
      const recuo = " ".repeat(largura + 2)

      state.renderList(node, recuo, (index) => {
        const numero = String(inicio + index)
        return `${" ".repeat(largura - numero.length)}${numero}. `
      })
    },
    list_item: (state, node) => {
      state.renderContent(node)
    },
    task_list: (state, node) => {
      state.renderList(node, "  ", () => "- ")
    },
    task_item: serializeTaskItem,
    paragraph: (state, node) => {
      state.renderInline(node)
      state.closeBlock(node)
    },
    image: (state, node) => {
      const alt = state.esc(node.attrs.alt || "")
      const src = node.attrs.src.replace(/[()]/g, "\\$&")
      const title = node.attrs.title ? ` "${node.attrs.title.replace(/"/g, '\\"')}"` : ""
      state.write(`![${alt}](${src}${title})`)
    },
    hard_break: (state, node, parent, index) => {
      // Duas barras invertidas seriam ruído: o padrão é dois espaços e quebra.
      for (let posterior = index + 1; posterior < parent.childCount; posterior++) {
        if (parent.child(posterior).type !== node.type) {
          state.write("\\\n")
          return
        }
      }
    },
    text: (state, node) => {
      state.text(node.text ?? "")
    },
  },
  {
    em: { open: "*", close: "*", mixable: true, expelEnclosingWhitespace: true },
    strong: { open: "**", close: "**", mixable: true, expelEnclosingWhitespace: true },
    strike: { open: "~~", close: "~~", mixable: true, expelEnclosingWhitespace: true },
    link: {
      open: () => "[",
      close: (_state, mark) => {
        const title = mark.attrs.title ? ` "${mark.attrs.title.replace(/"/g, '\\"')}"` : ""
        return `](${mark.attrs.href.replace(/[()]/g, "\\$&")}${title})`
      },
    },
    code: {
      open: (_state, _mark, parent, index) => backticksFor(parent.child(index), -1),
      close: (_state, _mark, parent, index) => backticksFor(parent.child(index - 1), 1),
      escape: false,
    },
  }
)

/** Quantas crases o trecho precisa para não colidir com o próprio conteúdo. */
function backticksFor(node: ProseNode, lado: number): string {
  const encontradas = /`+/g
  let quantidade = 0

  if (node.isText && node.text) {
    let achado = encontradas.exec(node.text)
    while (achado) {
      quantidade = Math.max(quantidade, achado[0].length)
      achado = encontradas.exec(node.text)
    }
  }

  let resultado = quantidade > 0 && lado > 0 ? " `" : "`"
  for (let contador = 0; contador < quantidade; contador++) resultado += "`"
  if (quantidade > 0 && lado < 0) resultado += " "

  return resultado
}

/** Atalhos usados pelo componente e por quem integra o editor. */
export function fromMarkdown(markdown: string): ProseNode {
  return markdownParser.parse(markdown ?? "")
}

export function toMarkdown(doc: ProseNode): string {
  return markdownSerializer.serialize(doc, { tightLists: true })
}

import {
  InputRule,
  inputRules,
  textblockTypeInputRule,
  wrappingInputRule,
} from "prosemirror-inputrules"
import type { MarkType } from "prosemirror-model"
import type { Plugin } from "prosemirror-state"

import { schema } from "@/components/ui/editor/schema"

/**
 * Regra de marca: ao fechar a marcação (`**forte**`), o texto entre os delimitadores
 * recebe a marca e os delimitadores somem — como no Linear e no Notion.
 */
function markRule(pattern: RegExp, type: MarkType): InputRule {
  return new InputRule(pattern, (state, match, start, end) => {
    const conteudo = match[1]
    if (!conteudo) return null

    const tr = state.tr
    const inicioTexto = start + match[0].indexOf(conteudo)
    const fimTexto = inicioTexto + conteudo.length

    // De trás para frente: apagar o fim primeiro mantém as posições do início válidas.
    if (fimTexto < end) tr.delete(fimTexto, end)
    if (inicioTexto > start) tr.delete(start, inicioTexto)

    return tr.addMark(start, start + conteudo.length, type.create()).removeStoredMark(type)
  })
}

/** Regras de digitação: Markdown vira formatação enquanto se escreve. */
export function buildInputRules(): Plugin {
  return inputRules({
    rules: [
      // Blocos
      textblockTypeInputRule(/^(#{1,3})\s$/, schema.nodes.heading, (match) => ({
        level: match[1].length,
      })),
      textblockTypeInputRule(/^```([a-z]*)?\s$/, schema.nodes.code_block, (match) => ({
        language: match[1] || null,
      })),
      wrappingInputRule(/^\s*>\s$/, schema.nodes.blockquote),
      wrappingInputRule(/^\s*[-+*]\s$/, schema.nodes.bullet_list),
      wrappingInputRule(
        /^(\d+)\.\s$/,
        schema.nodes.ordered_list,
        (match) => ({ order: Number(match[1]) }),
        (match, node) => node.childCount + node.attrs.order === Number(match[1])
      ),
      // "[ ] " no começo da linha abre uma lista de tarefas; o item nasce desmarcado.
      wrappingInputRule(/^\s*\[([ xX])\]\s$/, schema.nodes.task_list),
      new InputRule(/^(?:---|___|\*\*\*)\s$/, (state, _match, start, end) =>
        state.tr.replaceRangeWith(start, end, schema.nodes.horizontal_rule.create())
      ),

      // Marcas
      // O lookbehind evita capturar o caractere anterior: sem ele, o espaço antes
      // do delimitador entraria no trecho apagado.
      markRule(/(?<!\*)\*\*([^*]+)\*\*$/, schema.marks.strong),
      markRule(/(?<!_)__([^_]+)__$/, schema.marks.strong),
      markRule(/(?<![*\w])\*([^*]+)\*$/, schema.marks.em),
      markRule(/(?<![_\w])_([^_]+)_$/, schema.marks.em),
      markRule(/~~([^~]+)~~$/, schema.marks.strike),
      markRule(/`([^`]+)`$/, schema.marks.code),
    ],
  })
}

import {
  baseKeymap,
  chainCommands,
  createParagraphNear,
  exitCode,
  liftEmptyBlock,
  newlineInCode,
  splitBlock,
  toggleMark,
} from "prosemirror-commands"
import { redo, undo } from "prosemirror-history"
import { keymap } from "prosemirror-keymap"
import { liftListItem, sinkListItem, splitListItem } from "prosemirror-schema-list"
import type { Command, Plugin } from "prosemirror-state"

import {
  toggleBlockquote,
  toggleCodeBlock,
  toggleHeading,
  toggleList,
} from "@/components/ui/editor/commands"
import { schema } from "@/components/ui/editor/schema"

/** No Mac o modificador é ⌘; no resto, Ctrl. */
const isMac = typeof navigator !== "undefined" && /Mac|iP(hone|ad|od)/.test(navigator.platform)

type EditorKeymapOptions = {
  /** Chamado por Ctrl/⌘+Enter — costuma ser o "enviar" do formulário que hospeda o editor. */
  onSubmit?: () => void
}

/**
 * Enter dentro de lista divide o item; dentro de bloco de código, quebra a linha.
 * A ordem da cadeia é a prioridade: o primeiro comando que trata a tecla vence.
 */
const enterCommand: Command = chainCommands(
  splitListItem(schema.nodes.task_item),
  splitListItem(schema.nodes.list_item),
  newlineInCode,
  createParagraphNear,
  liftEmptyBlock,
  splitBlock
)

export function buildKeymap({ onSubmit }: EditorKeymapOptions = {}): Plugin[] {
  const atalhos: Record<string, Command> = {
    "Mod-z": undo,
    "Shift-Mod-z": redo,
    "Mod-y": redo,

    "Mod-b": toggleMark(schema.marks.strong),
    "Mod-i": toggleMark(schema.marks.em),
    "Mod-e": toggleMark(schema.marks.code),
    "Shift-Mod-x": toggleMark(schema.marks.strike),

    "Shift-Mod-1": toggleHeading(1),
    "Shift-Mod-2": toggleHeading(2),
    "Shift-Mod-3": toggleHeading(3),
    "Shift-Mod-8": toggleList(schema.nodes.bullet_list),
    "Shift-Mod-9": toggleList(schema.nodes.ordered_list),
    "Shift-Mod-7": toggleList(schema.nodes.task_list),
    "Shift-Mod-b": toggleBlockquote(),
    "Shift-Mod-c": toggleCodeBlock(),

    Enter: enterCommand,
    Tab: chainCommands(sinkListItem(schema.nodes.task_item), sinkListItem(schema.nodes.list_item)),
    "Shift-Tab": chainCommands(
      liftListItem(schema.nodes.task_item),
      liftListItem(schema.nodes.list_item)
    ),

    // Quebra de linha sem sair do parágrafo, e saída do bloco de código.
    "Shift-Enter": chainCommands(exitCode, (state, dispatch) => {
      if (dispatch) {
        dispatch(state.tr.replaceSelectionWith(schema.nodes.hard_break.create()).scrollIntoView())
      }
      return true
    }),
  }

  if (onSubmit) {
    atalhos["Mod-Enter"] = () => {
      onSubmit()
      return true
    }
  }

  if (isMac) atalhos["Ctrl-Enter"] = atalhos["Mod-Enter"] ?? (() => false)

  return [keymap(atalhos), keymap(baseKeymap)]
}

import { Plugin } from "prosemirror-state"
import { Decoration, DecorationSet } from "prosemirror-view"

/**
 * Texto de apoio no documento vazio. É uma decoração — nada entra no documento,
 * então o Markdown salvo continua vazio.
 */
export function placeholderPlugin(text: string): Plugin {
  return new Plugin({
    props: {
      decorations(state) {
        const doc = state.doc
        const vazio =
          doc.childCount === 1 && doc.firstChild?.isTextblock && doc.firstChild.content.size === 0

        if (!vazio) return null

        const decoracao = Decoration.node(0, doc.firstChild!.nodeSize, {
          class: "flynow-editor-placeholder",
          "data-placeholder": text,
        })

        return DecorationSet.create(doc, [decoracao])
      },
    },
  })
}

import { Plugin, PluginKey } from "prosemirror-state"
import { Decoration, DecorationSet } from "prosemirror-view"
import type { EditorView } from "prosemirror-view"

import { schema } from "@/components/ui/editor/schema"

/** O que o host devolve depois de guardar o arquivo. */
export type UploadedImage = { url: string; alt?: string | null }

export type UploadHandler = (file: File) => Promise<UploadedImage>

type UploadMeta =
  | { type: "start"; id: symbol; pos: number; name: string }
  | { type: "finish"; id: symbol }

const uploadKey = new PluginKey<DecorationSet>("flynow-editor-upload")

/**
 * Enquanto o arquivo sobe, um marcador ocupa o lugar da imagem. Ele é uma decoração,
 * então a digitação continua livre e a posição acompanha as edições feitas no meio-tempo.
 */
function uploadPlaceholderPlugin(): Plugin<DecorationSet> {
  return new Plugin<DecorationSet>({
    key: uploadKey,
    state: {
      init: () => DecorationSet.empty,
      apply(tr, conjunto) {
        let atual = conjunto.map(tr.mapping, tr.doc)
        const meta = tr.getMeta(uploadKey) as UploadMeta | undefined

        if (meta?.type === "start") {
          const marcador = document.createElement("span")
          marcador.className = "flynow-editor-uploading"
          marcador.textContent = `Enviando ${meta.name}...`

          atual = atual.add(tr.doc, [Decoration.widget(meta.pos, marcador, { id: meta.id })])
        }

        if (meta?.type === "finish") {
          atual = atual.remove(atual.find(undefined, undefined, (spec) => spec.id === meta.id))
        }

        return atual
      },
    },
    props: {
      decorations: (state) => uploadKey.getState(state),
    },
  })
}

/** Onde o marcador está agora — ele se move se o texto ao redor mudar. */
function findPlaceholder(view: EditorView, id: symbol): number | null {
  const conjunto = uploadKey.getState(view.state)
  const encontrado = conjunto?.find(undefined, undefined, (spec) => spec.id === id)

  return encontrado?.length ? encontrado[0].from : null
}

async function upload(view: EditorView, file: File, pos: number, handler: UploadHandler) {
  const id = Symbol(file.name)

  view.dispatch(view.state.tr.setMeta(uploadKey, { type: "start", id, pos, name: file.name }))

  try {
    const { url, alt } = await handler(file)
    const destino = findPlaceholder(view, id)

    const tr = view.state.tr.setMeta(uploadKey, { type: "finish", id })
    if (destino !== null) {
      tr.replaceWith(destino, destino, schema.nodes.image.create({ src: url, alt: alt ?? file.name }))
    }

    view.dispatch(tr)
  } catch {
    // Falhou: só o marcador sai, o texto que a pessoa escreveu no meio-tempo fica.
    view.dispatch(view.state.tr.setMeta(uploadKey, { type: "finish", id }))
  }
}

function imageFiles(list: FileList | null | undefined): File[] {
  return Array.from(list ?? []).filter((file) => file.type.startsWith("image/"))
}

/**
 * Colar e arrastar imagens. Sem `handler` o plugin não intercepta nada — o editor
 * segue funcionando como texto puro em quem não tem onde guardar arquivo.
 */
export function imageUploadPlugin(handler?: UploadHandler): Plugin[] {
  if (!handler) return []

  const eventos = new Plugin({
    props: {
      handlePaste(view, event) {
        const arquivos = imageFiles(event.clipboardData?.files)
        if (arquivos.length === 0) return false

        event.preventDefault()
        const pos = view.state.selection.from
        arquivos.forEach((file) => void upload(view, file, pos, handler))

        return true
      },

      handleDrop(view, event) {
        const arquivos = imageFiles((event as DragEvent).dataTransfer?.files)
        if (arquivos.length === 0) return false

        event.preventDefault()
        const coordenadas = view.posAtCoords({
          left: (event as DragEvent).clientX,
          top: (event as DragEvent).clientY,
        })
        const pos = coordenadas?.pos ?? view.state.selection.from
        arquivos.forEach((file) => void upload(view, file, pos, handler))

        return true
      },
    },
  })

  return [uploadPlaceholderPlugin(), eventos]
}

/** Sobe um arquivo escolhido pelo botão da barra, na posição do cursor. */
export function uploadImageFile(view: EditorView, file: File, handler: UploadHandler): void {
  void upload(view, file, view.state.selection.from, handler)
}
